"""
Registro encadenado: un diario al que solo se añade por el final y en el que
no se puede retocar una línea vieja sin que se note.

El truco: cada línea guarda una huella (un número largo calculado a partir de
su propio contenido) y también la huella de la línea anterior. Si alguien
cambia una coma de la línea 3, su huella deja de cuadrar y todas las de abajo
se quedan colgando. Es lo mismo que hace una cadena de bloques, sin cadena de
bloques.

Regla dura: aquí NUNCA entra un dato personal. Se guarda qué se hizo, cuánto
costó y quién lo pidió, no el contenido de la consulta.
"""

import hashlib
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

from redactor import hay_datos_personales

CARPETA = Path(__file__).resolve().parent
FICHERO = CARPETA / "registro.jsonl"
SEMILLA = "0" * 64  # La huella imaginaria de la línea cero.

# Campos que no se revisan porque son huellas, no texto de nadie.
CAMPOS_TECNICOS = {"huella", "anterior", "cuando"}


def _huella(texto):
    """SHA-256: convierte cualquier texto en 64 letras y números fijos."""
    return hashlib.sha256(texto.encode("utf-8")).hexdigest()


def _ultima_huella():
    if not FICHERO.exists():
        return SEMILLA
    ultima = SEMILLA
    # utf-8-sig: si el Bloc de notas guardó el fichero con una marca invisible
    # al principio, se ignora esa marca en vez de reventar.
    with FICHERO.open("r", encoding="utf-8-sig") as fichero:
        for linea in fichero:
            linea = linea.strip()
            if linea:
                ultima = json.loads(linea)["huella"]
    return ultima


def _revisa_que_no_haya_datos_personales(evento):
    for clave, valor in evento.items():
        if clave in CAMPOS_TECNICOS:
            continue
        if isinstance(valor, str) and hay_datos_personales(valor):
            raise ValueError(
                "El campo '%s' lleva un dato personal sin tapar. "
                "No se escribe en el registro." % clave
            )


def apunta(evento):
    """Añade una línea al final del diario. Nunca se edita ni se borra nada."""
    _revisa_que_no_haya_datos_personales(evento)

    linea = {"cuando": datetime.now(timezone.utc).isoformat(timespec="seconds")}
    linea["anterior"] = _ultima_huella()
    linea.update(evento)
    linea["huella"] = _huella(json.dumps(linea, sort_keys=True, ensure_ascii=False))

    with FICHERO.open("a", encoding="utf-8") as fichero:
        fichero.write(json.dumps(linea, ensure_ascii=False) + "\n")
    return linea


def verifica():
    """
    Recorre el diario de arriba abajo y comprueba que nadie ha tocado nada.
    Devuelve (True/False, mensaje).
    """
    if not FICHERO.exists():
        return True, "El diario está vacío: todavía no hay nada que verificar."

    anterior = SEMILLA
    total = 0

    with FICHERO.open("r", encoding="utf-8-sig") as fichero:
        for numero, linea in enumerate(fichero, start=1):
            linea = linea.strip()
            if not linea:
                continue
            total += 1

            try:
                guardado = json.loads(linea)
            except json.JSONDecodeError:
                return False, "Línea %d: ya no es JSON válido. La han roto." % numero

            huella = guardado.pop("huella", None)

            if guardado.get("anterior") != anterior:
                return False, (
                    "Línea %d: no engancha con la anterior. O falta una línea "
                    "o han cambiado el orden." % numero
                )

            recalculada = _huella(json.dumps(guardado, sort_keys=True, ensure_ascii=False))
            if recalculada != huella:
                return False, (
                    "Línea %d: el contenido no coincide con su huella. "
                    "Alguien ha editado esta línea." % numero
                )

            anterior = huella

    return True, "%d líneas verificadas. La cadena está intacta." % total


def ultimas(cuantas=5):
    """Las últimas líneas del diario, para mirarlas por encima."""
    if not FICHERO.exists():
        return []
    texto = FICHERO.read_text(encoding="utf-8-sig")
    lineas = []
    for cruda in texto.splitlines():
        if not cruda.strip():
            continue
        try:
            lineas.append(json.loads(cruda))
        except json.JSONDecodeError:
            lineas.append({"tipo": "ILEGIBLE", "cuando": "?"})
    return lineas[-cuantas:]


if __name__ == "__main__":
    correcto, mensaje = verifica()
    print(("OK      " if correcto else "ALARMA  ") + mensaje)
    for linea in ultimas(5):
        print("  %s  %-9s  %s" % (
            linea.get("cuando", "?"),
            linea.get("tipo", "?"),
            linea.get("accion") or linea.get("modelo") or "",
        ))
    sys.exit(0 if correcto else 1)
